<script setup lang="ts">
import { ref, watch } from 'vue'
import { Save, RotateCcw, ShieldCheck, Settings2, CheckCircle2 } from '@lucide/vue'
import { clone, state, saveConfiguration, perform, refresh, notify } from '../../app/state'
import type { Configuration } from '../../app/types'
import { api } from '../../app/api'
const draft = ref<Configuration>(); const token=ref('');const clearToken=ref(false);const proxy=ref('');const clearProxy=ref(false);const busy=ref(false);const checks=ref<Record<string,unknown>>()
watch(()=>state.config?.revision,()=>{if(state.config)draft.value=clone(state.config.config)},{immediate:true})
async function save() { if(!draft.value)return;busy.value=true;try{await saveConfiguration(draft.value,clearToken.value?'':token.value||undefined,clearProxy.value?'':proxy.value||undefined);token.value='';clearToken.value=false;proxy.value='';clearProxy.value=false}finally{busy.value=false} }
async function reload() { await api('/config/reload','POST');await refresh();notify('已重新载入磁盘配置') }
async function check() { checks.value=await api('/system/checks') }
</script>
<template><section v-if="draft"><div class="page-heading"><div><span class="eyebrow">SYSTEM PREFERENCES</span><h1>系统设置<span>.</span></h1><p>设置写回当前 YAML，运行中的任务继续使用原始快照。</p></div><div class="heading-actions"><button class="button" @click="perform(reload)"><RotateCcw :size="16"/>重新载入配置</button><button class="button primary" :disabled="busy" @click="perform(save)"><Save :size="16"/>{{busy?'保存中…':'保存设置'}}</button></div></div><div v-if="state.config?.restart_required" class="alert warning">监听、目录或 TLS 设置已修改。请重启程序后生效。</div><div class="settings-grid"><section class="panel settings-panel"><div class="section-heading"><Settings2 :size="18"/><h3>同步执行</h3></div><label>任务累计超时<input v-model="draft.settings.task_timeout" placeholder="8h"/><small>切换来源、继续执行共享预算；排队与暂停不计时。</small></label><div class="form-grid"><label>rsync I/O 超时<input v-model="draft.settings.rsync.io_timeout" placeholder="5m"/></label><label>rsync 连接超时<input v-model="draft.settings.rsync.connect_timeout" placeholder="30s"/></label></div><label>rsync 传输限速 · MB/s<input v-model.number="draft.settings.rsync.limit_mb" type="number" min="0" step="any"/><small>十进制 MB/s；0 不限速。仅限制每个上游同步任务。</small></label></section><section class="panel settings-panel"><div class="section-heading"><ShieldCheck :size="18"/><h3>GitHub Release</h3></div><label>默认最近 N 个 Release<input v-model.number="draft.settings.github.release_count" type="number" min="1" max="100"/><small>单个同步源可覆盖；始终忽略草稿与自动源码归档。</small></label><label>GitHub Token<input v-model="token" type="password" autocomplete="new-password" :placeholder="state.config?.token_configured?'已配置，留空保留现有 Token':'未配置，可直接粘贴 Token'"/><small>保存后输入框清空，读取 API 不返回凭证。</small></label><label>GitHub 代理 · proxy<input v-model="proxy" type="password" autocomplete="new-password" :placeholder="state.config?.proxy_configured?'已配置，留空保留现有代理':'http://127.0.0.1:8081 或 socks5://127.0.0.1:1080'"/><small>API 和附件共用代理；支持 HTTP/HTTPS、SOCKS5。未配置时直连，不读取系统代理。代理地址可能含密码，读取 API 不返回原值。</small></label><div class="check-stack"><label class="check"><input v-model="draft.settings.github.include_prereleases" type="checkbox"/>包含预发布版本</label><label class="check"><input v-model="draft.settings.github.prune_old_releases" type="checkbox"/>成功后清理超出数量的旧版本</label><label class="check"><input v-model="clearToken" type="checkbox"/>清空现有 Token</label><label class="check"><input v-model="clearProxy" type="checkbox"/>清空代理并直连</label></div></section><section class="panel settings-panel"><div class="section-heading"><Settings2 :size="18"/><h3>监听与目录</h3><span class="type-pill">重启生效</span></div><div class="form-grid"><label>listen<input v-model="draft.listen"/></label><label>port<input v-model.number="draft.port" type="number" min="1" max="65535"/></label></div><label>数据库与日志 · path<input v-model="draft.path"/><small>数据库固定为 data.sqlite，源镜像目录单独存放。</small></label><label>镜像根 · mirror_root<input v-model="draft.mirror_root"/></label></section><section class="panel settings-panel"><div class="section-heading"><ShieldCheck :size="18"/><h3>TLS 证书</h3><span class="type-pill">重启生效</span></div><label>证书链 · cert<input v-model="draft.tls.cert" placeholder="./certs/fullchain.pem"/></label><label>私钥 · key<input v-model="draft.tls.key" placeholder="./certs/privkey.pem"/></label><p class="setting-note">两项留空提供 HTTP，填齐提供 HTTPS。相对路径以配置文件目录为基准；不匹配或不可读会报错。</p><p class="setting-note">HTTP 文件下载优先使用 sendfile；HTTPS 使用 TLS 流式传输。</p></section></div><section class="panel config-footer"><div><span class="eyebrow">ACTIVE CONFIGURATION</span><code>{{state.config?.file}}</code><small>时区：{{state.info?.timezone}} · Go {{state.info?.go}} · 记录永久保存</small></div><button class="button" @click="perform(check)"><CheckCircle2 :size="16"/>检查运行环境</button><pre v-if="checks">{{JSON.stringify(checks,null,2)}}</pre></section></section></template>
